import json
import pandas as pd
from datetime import datetime

FIELD_MAP = {
    "user_id": ["user_id", "id", "userId"],
    "name":    ["full_name", "name", "userName"],
    "email":   ["email", "email_address"],
    "created_date": ["registration_date", "created_at", "joined"],
}

OUTPUT_COLS = ["user_id", "name", "email", "created_date", "status"]


def normalize_date(val):
    if pd.isna(val) or val is None:
        return None
    s = str(val).strip()
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d-%m-%Y", "%Y/%m/%d"):
        try:
            return datetime.strptime(s, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    return s


def remap(df: pd.DataFrame) -> pd.DataFrame:
    rename = {}
    for unified, variants in FIELD_MAP.items():
        for col in df.columns:
            if col in variants and col != unified:
                rename[col] = unified
    df = df.rename(columns=rename)
    # keep only known columns that exist
    keep = [c for c in OUTPUT_COLS if c in df.columns]
    df = df[keep]
    return df


def load_source_a(path):
    with open(path) as f:
        data = json.load(f)
    df = pd.DataFrame(data)
    df = remap(df)
    return df


def load_source_b(path):
    df = pd.read_csv(path)
    df = remap(df)
    return df


def load_source_c(path):
    df = pd.read_parquet(path)
    df = remap(df)
    return df


def to_record(df: pd.DataFrame) -> dict:
    """Return {user_id: {field: value}} dict, skipping NaN."""
    records = {}
    for _, row in df.iterrows():
        uid = int(row["user_id"])
        rec = {}
        for col in OUTPUT_COLS:
            if col in row.index and not pd.isna(row[col]):
                val = row[col]
                if col == "created_date":
                    val = normalize_date(val)
                rec[col] = val
        records[uid] = rec
    return records


def merge(sources: list[tuple[str, dict]]) -> tuple[list[dict], list[dict]]:
    """
    sources: list of (source_name, record_dict) in priority order (highest first).
    Returns (merged_rows, conflicts).
    """
    all_ids = set()
    for _, recs in sources:
        all_ids.update(recs.keys())

    merged_rows = []
    conflicts = []

    for uid in sorted(all_ids):
        present = [(name, recs[uid]) for name, recs in sources if uid in recs]
        if len(present) == 1:
            row = {"user_id": uid, **present[0][1]}
            merged_rows.append(row)
            continue

        # build merged row using priority order
        row = {"user_id": uid}
        for field in [f for f in OUTPUT_COLS if f != "user_id"]:
            values_by_source = {
                name: rec[field]
                for name, rec in present
                if field in rec
            }
            if not values_by_source:
                continue

            # selected = value from highest-priority source that has the field
            selected = next(
                (v for _, v in present if field in {k: v for k, v in [(n, r.get(field)) for n, r in present] if v is not None}),
                None,
            )
            # simpler: iterate present in priority order
            selected = None
            for name, rec in present:
                if field in rec:
                    selected = rec[field]
                    break

            row[field] = selected

            # conflict = any source has a different non-None value
            unique_vals = set(values_by_source.values())
            if len(unique_vals) > 1:
                conflicts.append({
                    "user_id": uid,
                    "field": field,
                    "values": {
                        src: values_by_source[src]
                        for src in ["source_a", "source_b", "source_c"]
                        if src in values_by_source
                    },
                    "selected": selected,
                })

        merged_rows.append(row)

    return merged_rows, conflicts


def main():
    src_a = to_record(load_source_a("/data/source_a/users.json"))
    src_b = to_record(load_source_b("/data/source_b/users.csv"))
    src_c = to_record(load_source_c("/data/source_c/users.parquet"))

    sources = [
        ("source_a", src_a),
        ("source_b", src_b),
        ("source_c", src_c),
    ]

    merged_rows, conflicts = merge(sources)

    # Build DataFrame
    df = pd.DataFrame(merged_rows)
    df["user_id"] = df["user_id"].astype(int)
    for col in OUTPUT_COLS:
        if col not in df.columns:
            df[col] = None
    df = df[OUTPUT_COLS]

    df.to_parquet("/app/merged_users.parquet", index=False)
    print(f"Wrote {len(df)} rows to /app/merged_users.parquet")

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w") as f:
        json.dump(report, f, indent=2)
    print(f"Wrote conflict report with {len(conflicts)} conflicts to /app/conflicts.json")


if __name__ == "__main__":
    main()

